insert into public.organizations (id,name,slug,status,timezone) values ('b3000000-0000-4000-8000-000000000012','Upsert org','upsert-org','active','UTC');
insert into public.users (id,auth_user_id,email,display_name) values ('b3000000-0000-4000-8000-000000000013','b3000000-0000-4000-8000-000000000010','upsert@test.local','Upsert owner');
insert into public.profiles (id,user_id,organization_id,role_id,display_name) values ('b3000000-0000-4000-8000-000000000014','b3000000-0000-4000-8000-000000000013','b3000000-0000-4000-8000-000000000012','b3000000-0000-4000-8000-000000000011','Upsert owner');
insert into public.events (id,organization_id,name,event_type,status,start_at,timezone,venue,operational_model) values ('b3000000-0000-4000-8000-000000000015','b3000000-0000-4000-8000-000000000012','Upsert event','nightlife','published','2026-09-10T20:00:00Z','UTC','Upsert venue','mixed');
select set_config('request.jwt.claims','{"sub":"b3000000-0000-4000-8000-000000000010","role":"authenticated"}',true);
select ok((select enabled from public.upsert_reporting_destination('b3000000-0000-4000-8000-000000000015','sheet-a',true)),'create enabled');
select ok(not (select enabled from public.upsert_reporting_destination('b3000000-0000-4000-8000-000000000015','sheet-a',false)),'false persists');
select ok((select enabled from public.upsert_reporting_destination('b3000000-0000-4000-8000-000000000015','sheet-a',true)),'true persists');
update public.reporting_destinations set last_success_dataset_hash='hash',last_success_spreadsheet_id='sheet-a',last_success_sheet_schema_version=1 where event_id='b3000000-0000-4000-8000-000000000015';
